    },
    "reason": {
      "type": "string",
      "description": "Why the credential is needed; shown to the user in the prompt"
    }
  },
  "required": [
    "name",
    "reason"
  ]
}

{
  "type": "object",
  "properties": {
    "prompt": {
      "type": "string",
