+    final value = int.parse(match.group(1)!);
+    totalMs += switch (match.group(2)!) {
+      'h' => value * 60 * 60 * 1000,
+      'm' => value * 60 * 1000,
+      _ => value * 1000,
+    };
+    pos = match.end;
+  }
