+  final hours = seconds ~/ 3600;
+  final minutes = (seconds % 3600) ~/ 60;
+  if (hours > 0) return minutes > 0 ? '${hours}h${minutes}m' : '${hours}h';
+  if (minutes > 0) return '${minutes}min';
+  return '${seconds}s';
+}
