+    CancelToken? cancelToken,
+  }) {
+    contexts.add(context);
+    final stream = AssistantMessageEventStream();
+    final turn = turns.isEmpty ? textTurn('idle') : turns.removeAt(0);
+    for (final event in turn) {
+      stream.push(event);
+    }
+    stream.end();
+    return stream;
+  }
